import{_ as a,c as t,o as l,a3 as r}from"./chunks/framework.BusRvirq.js";const d=JSON.parse('{"title":"소프트웨어 프리랜서 업무위탁 용역계약서","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/public/templates/14_Freelancer_Agreement_template.html"}]]},"headers":[],"relativePath":"public/templates/14_Freelancer_Agreement_template.md","filePath":"public/templates/14_Freelancer_Agreement_template.md","lastUpdated":1790810085000}'),o={name:"public/templates/14_Freelancer_Agreement_template.md"};function i(n,e,_,c,s,p){return l(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="소프트웨어-프리랜서-업무위탁-용역계약서" tabindex="-1">소프트웨어 프리랜서 업무위탁 용역계약서 <a class="header-anchor" href="#소프트웨어-프리랜서-업무위탁-용역계약서" aria-label="Permalink to “소프트웨어 프리랜서 업무위탁 용역계약서”">​</a></h1><p>주식회사 엠파시(이하 &quot;회사&quot;라 한다)와 독립 전문 프리랜서 [성명](이하 &quot;수탁자&quot;라 한다)은 상호 신뢰를 바탕으로 다음과 같이 업무위탁 용역계약을 체결한다.</p><h3 id="제1조-독립-사업자-지위의-확인-근로자성-배제-명문화" tabindex="-1">제1조 (독립 사업자 지위의 확인 - 근로자성 배제 명문화) <a class="header-anchor" href="#제1조-독립-사업자-지위의-확인-근로자성-배제-명문화" aria-label="Permalink to “제1조 (독립 사업자 지위의 확인 - 근로자성 배제 명문화)”">​</a></h3><ol><li>&quot;수탁자&quot;는 독자적인 전문성에 기초하여 과업을 완수하는 독립된 개인 사업소득자로서 근로기준법상 근로자가 아님을 상호 확인한다.</li><li>&quot;수탁자&quot;의 출퇴근 시간 및 작업 장소는 과업 일정에 지장이 없는 한 &quot;수탁자&quot;의 자율에 따른다.</li><li>용역 대금 지급 시 3.3% 사업소득세를 원천징수하며, 4대 사회보험 및 퇴직금 지급 대상이 아님을 확인한다.</li></ol><h3 id="제2조-용역-대금-및-지급" tabindex="-1">제2조 (용역 대금 및 지급) <a class="header-anchor" href="#제2조-용역-대금-및-지급" aria-label="Permalink to “제2조 (용역 대금 및 지급)”">​</a></h3><ul><li>총 계약 금액: 일금 [ ] 원 (세전)</li><li>지급 시기: 매월 [ 25 ]일 마일스톤 검수 완료 후 지급</li></ul><h3 id="제3조-저작권-귀속-및-소스-반출-금지" tabindex="-1">제3조 (저작권 귀속 및 소스 반출 금지) <a class="header-anchor" href="#제3조-저작권-귀속-및-소스-반출-금지" aria-label="Permalink to “제3조 (저작권 귀속 및 소스 반출 금지)”">​</a></h3><ol><li>&quot;수탁자&quot;가 작성한 소스코드의 저작재산권은 대금 수령과 동시에 &quot;회사&quot;에 전속 귀속된다.</li><li>&quot;수탁자&quot;는 회사의 소스코드를 개인 저장소에 올리거나 외부에 반출할 수 없으며, 계약 종료 즉시 로컬 파일을 영구 파기한다.</li></ol><p>체결일자: 202 년 월 일 [회사] 주식회사 엠파시 대표이사 [ ] (인) [수탁자] 성명: [ ] (주민번호: ) (인)</p>',9)])])}const u=a(o,[["render",i]]);export{d as __pageData,u as default};
